sys_script.script:
(function executeRule(current, previous /*null when async*/) {

var contactTable = new GlideRecord('customer_contact');
var tradeCase = new GlideRecord('x_hsb11_hsbc_mss_t_trade_case');

gs.info('u_counterparty_code'+current.counterparty_code);
gs.info(('business_process'+current.business_process));
tradeCase.addQuery('u_counterparty_code', current.counterparty_code);
//bpInstance.business_process_definition = contactTable.setDisplayValue(u_business_process);

//contactTable.addQuery('u_business_process', 'businessProcess');	
contactTable.query();
if (contactTable.next()) {
if(contactTable.u_email_automation==yes)
	{


		tradeCase.does_client_prefer_proactive_contact = 'Yes';  //Trade case

	}
	else
		{
			tradeCase.does_client_prefer_proactive_contact = 'No';  //
		}
	tradeCase.update();
//tradeCase.initialize();

//tradeCase.does_client_prefer_proactive_contact = contactTable.u_email_automation;

}

})(current, previous);
